import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as o}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Pi Agent 设计哲学","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/agent/pi-agent-design-philosophy.md","filePath":"zh/tech/agent/pi-agent-design-philosophy.md","lastUpdated":1780925527000}'),i={name:"zh/tech/agent/pi-agent-design-philosophy.md"};function s(l,t,r,d,p,h){return n(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="pi-agent-设计哲学" tabindex="-1">Pi Agent 设计哲学 <a class="header-anchor" href="#pi-agent-设计哲学" aria-label="Permalink to &quot;Pi Agent 设计哲学&quot;">​</a></h1><blockquote><p>源码：<a href="https://github.com/badlogic/pi-mono" target="_blank" rel="noreferrer">mariozechner/pi-mono</a>，来自 @badlogic 的博客文章</p></blockquote><h2 id="核心观点" tabindex="-1">核心观点 <a class="header-anchor" href="#核心观点" aria-label="Permalink to &quot;核心观点&quot;">​</a></h2><p>构建 Agent 的核心理念：<strong>&quot;如果我不需要它，它就不会被构建。&quot;</strong></p><p>Pi 是一个极简的代码 Agent，专注于控制感和可观测性，而非功能堆砌。</p><hr><h2 id="pi-ai-统一-llm-api" tabindex="-1">pi-ai：统一 LLM API <a class="header-anchor" href="#pi-ai-统一-llm-api" aria-label="Permalink to &quot;pi-ai：统一 LLM API&quot;">​</a></h2><h3 id="四大-api-搞定一切" tabindex="-1">四大 API 搞定一切 <a class="header-anchor" href="#四大-api-搞定一切" aria-label="Permalink to &quot;四大 API 搞定一切&quot;">​</a></h3><p>本质上只需要对接 4 个 API：</p><ul><li>OpenAI Chat API</li><li>OpenAI Responses API</li><li>Anthropic Messages API</li><li>Google Generative AI API</li></ul><h3 id="context-handoff-跨模型上下文迁移" tabindex="-1">Context Handoff（跨模型上下文迁移） <a class="header-anchor" href="#context-handoff-跨模型上下文迁移" aria-label="Permalink to &quot;Context Handoff（跨模型上下文迁移）&quot;">​</a></h3><p>Pi-ai 从一开始就是为跨 Provider 上下文迁移设计的。例如从 Anthropic 切换到 OpenAI 时，Anthropic 的 thinking traces 会转换为 <code>&lt;thinking&gt;&lt;/thinking&gt;</code> 标签包裹的文本。</p><h3 id="structured-split-tool-results" tabindex="-1">Structured Split Tool Results <a class="header-anchor" href="#structured-split-tool-results" aria-label="Permalink to &quot;Structured Split Tool Results&quot;">​</a></h3><p>Tool 返回结果分为两部分：</p><ul><li><strong>LLM 部分</strong>：纯文本或 JSON</li><li><strong>UI 部分</strong>：结构化数据 + 附件（图片等）</li></ul><p>这种分离让 UI 渲染和 LLM 上下文各取所需，避免用文本解析来构建 UI。</p><h3 id="极简-agent-loop" tabindex="-1">极简 Agent Loop <a class="header-anchor" href="#极简-agent-loop" aria-label="Permalink to &quot;极简 Agent Loop&quot;">​</a></h3><p>Agent Loop 不提供 <code>max steps</code> 这类参数——只管循环直到模型输出非 Tool Call 的响应。<code>pi-agent-core</code> 在此基础上提供：状态管理、事件订阅、消息队列、附件处理。</p><hr><h2 id="pi-coding-agent-极简代码-agent" tabindex="-1">pi-coding-agent：极简代码 Agent <a class="header-anchor" href="#pi-coding-agent-极简代码-agent" aria-label="Permalink to &quot;pi-coding-agent：极简代码 Agent&quot;">​</a></h2><h3 id="极简-system-prompt" tabindex="-1">极简 System Prompt <a class="header-anchor" href="#极简-system-prompt" aria-label="Permalink to &quot;极简 System Prompt&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are an expert coding assistant. You help users with coding tasks by reading files, executing commands, editing code, and writing new files.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Available tools:</span></span>
<span class="line"><span>- read: Read file contents</span></span>
<span class="line"><span>- bash: Execute bash commands</span></span>
<span class="line"><span>- edit: Make surgical edits to files</span></span>
<span class="line"><span>- write: Create or overwrite files</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Guidelines:</span></span>
<span class="line"><span>- Use bash for file operations like ls, grep, find</span></span>
<span class="line"><span>- Use read to examine files before editing</span></span>
<span class="line"><span>- Use edit for precise changes (old text must match exactly)</span></span>
<span class="line"><span>- Use write only for new files or complete rewrites</span></span>
<span class="line"><span>- Be concise in your responses</span></span>
<span class="line"><span>- Show file paths clearly when working with files</span></span></code></pre></div><p>整个 System Prompt + Tools 不到 1000 tokens。</p><h3 id="极简-toolset-四个工具" tabindex="-1">极简 Toolset（四个工具） <a class="header-anchor" href="#极简-toolset-四个工具" aria-label="Permalink to &quot;极简 Toolset（四个工具）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><code>read</code></td><td>读取文件内容</td></tr><tr><td><code>write</code></td><td>创建/覆盖文件</td></tr><tr><td><code>edit</code></td><td>精确替换（oldText 必须完全匹配）</td></tr><tr><td><code>bash</code></td><td>执行命令行</td></tr></tbody></table><p><strong>结论：4 个工具足以构建一个高效的代码 Agent。</strong></p><h3 id="yolo-by-default" tabindex="-1">YOLO by Default <a class="header-anchor" href="#yolo-by-default" aria-label="Permalink to &quot;YOLO by Default&quot;">​</a></h3><p>Pi 默认运行在完全 YOLO 模式：无权限检查、无安全护栏、无预检查命令。</p><p>作者认为：一旦 Agent 能写代码并执行代码，&quot;安全护栏&quot;基本是安全 theater。真正的保护只有通过网络隔离实现，而这会让 Agent 变得无用。所以默认 YOLO，用容器来隔离。</p><h3 id="不做这些-opinionated-no" tabindex="-1">不做这些（Opinionated No） <a class="header-anchor" href="#不做这些-opinionated-no" aria-label="Permalink to &quot;不做这些（Opinionated No）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不做的功能</th><th>原因</th></tr></thead><tbody><tr><td>内置 To-Do</td><td>To-Do 增加模型需要跟踪的状态，引入了更多出错机会</td></tr><tr><td>Plan Mode</td><td>协作式思考用自然语言就够了，持久规划写文件</td></tr><tr><td>MCP 支持</td><td>MCP Server 太大（21 工具 / 13.7k tokens），改用 CLI 工具 + README 按需加载</td></tr><tr><td>后台 Bash</td><td>用 tmux 代替，tmux 本身就能管理后台进程</td></tr><tr><td>Sub-Agent</td><td>需要时用 <code>bash</code> 启动新的 pi session，不内置</td></tr></tbody></table><h3 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to &quot;替代方案&quot;">​</a></h3><ul><li><strong>To-Do</strong>：用 <code>TODO.md</code> 文件代替</li><li><strong>Plan</strong>：用 <code>PLAN.md</code> 文件代替</li><li><strong>MCP</strong>：构建带 README 的 CLI 工具，Agent 按需读取（渐进式加载 token）</li><li><strong>后台进程</strong>：用 tmux 管理</li><li><strong>Sub-Agent</strong>：用 bash 启动新的 pi session + tmux</li></ul><hr><h2 id="pi-tui-保留模式-ui" tabindex="-1">pi-tui：保留模式 UI <a class="header-anchor" href="#pi-tui-保留模式-ui" aria-label="Permalink to &quot;pi-tui：保留模式 UI&quot;">​</a></h2><h3 id="两种-tui-模式" tabindex="-1">两种 TUI 模式 <a class="header-anchor" href="#两种-tui-模式" aria-label="Permalink to &quot;两种 TUI 模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>特点</th><th>代表</th></tr></thead><tbody><tr><td>全屏模式</td><td>接管整个终端视口，像像素缓冲区一样处理</td><td>Amp、opencode</td></tr><tr><td>追加模式</td><td>像普通 CLI 一样追加内容，只在需要更新时回写</td><td>Claude Code、Codex、pi</td></tr></tbody></table><p>Pi 选择追加模式，复用终端原生的滚动和搜索功能。</p><h3 id="差分渲染-differential-rendering" tabindex="-1">差分渲染（Differential Rendering） <a class="header-anchor" href="#差分渲染-differential-rendering" aria-label="Permalink to &quot;差分渲染（Differential Rendering）&quot;">​</a></h3><p>渲染算法：</p><ol><li>首次渲染：直接输出所有行</li><li>宽度改变：清屏重绘</li><li>正常更新：找到第一行差异处，光标移到那行，从那里重绘到最后</li></ol><p>用 ANSI 同步输出序列（CSI ?2026h/l）防止闪烁。</p><hr><h2 id="性能基准" tabindex="-1">性能基准 <a class="header-anchor" href="#性能基准" aria-label="Permalink to &quot;性能基准&quot;">​</a></h2><p>Terminal-Bench 2.0 结果：Pi + Claude Opus 4.5 排名靠前，与内置 Agent 原生提示的模型竞争。</p><hr><h2 id="关键设计原则" tabindex="-1">关键设计原则 <a class="header-anchor" href="#关键设计原则" aria-label="Permalink to &quot;关键设计原则&quot;">​</a></h2><ol><li><strong>控制 &gt; 功能</strong>：保持对所有交互的完全可观测性</li><li><strong>极简 &gt; 堆砌</strong>：不加不需要的功能</li><li><strong>Token 效率</strong>：渐进式上下文加载，避免 context rot</li><li><strong>YOLO 信任</strong>：默认完全信任用户，用容器做隔离</li><li><strong>工具即 CLI</strong>：不用 MCP，用带 README 的命令行工具按需加载</li></ol>`,48)])])}const f=e(i,[["render",s]]);export{m as __pageData,f as default};
